const t={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Znajdź najwyższy przepływ objętościowy (mm³/s), jaki Twój hotend utrzyma - zwiększając przepływ i obserwując odczyt obciążenia StallGuard ekstrudera w poszukiwaniu momentu poślizgu koła. Najpierw podejrzyj plan; test na żywo nagrzewa i wytłacza, więc przygotuj drukarkę przed uruchomieniem."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Pomoc"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"O Max-Flow"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Zamknij"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Jak używać"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Ustaw temperaturę testu i średnicę filamentu (wybierz hotend, by uzupełnić pola)."}},{t:0,b:{t:2,i:[{t:3}],s:"Podejrzyj plan - pokazuje każdy krok przepływu i ile filamentu wytłacza."}},{t:0,b:{t:2,i:[{t:3}],s:"Odhacz listę kontrolną bezpieczeństwa, a następnie uruchom test na żywo (nagrzewa + wytłacza)."}},{t:0,b:{t:2,i:[{t:3}],s:"Odczytaj maksymalny utrzymywany przepływ i skopiuj sugerowaną wartość do slicera."}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Jak działa test"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Ekstruder wytłacza filament ze stale rosnącym przepływem objętościowym. Dopóki radełkowane koło chwyta czysto, odczyt obciążenia StallGuard pozostaje stabilny; gdy zaczyna się poślizg, odczyty zaczynają skakać. Najwyższy przepływ osiągnięty przed tym skokiem to Twój utrzymywany maksymalny przepływ. Narastanie zatrzymuje się natychmiast po wykryciu poślizgu, więc żaden filament nie jest mielony po pierwszym poślizgu."}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:"Wykrywanie poślizgu StallGuard"}},body:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard to funkcja sterownika TMC raportująca obciążenie silnika. Ten test próbkuje je wielokrotnie na każdym kroku przepływu i szuka nagłego wzrostu rozrzutu (IQR) lub zmienności (CV) - sygnatury utraty chwytu przez koło. Progi pochodzą z profilu dla danego sterownika. Uwaga: na ekstruderze z TMC2209 wykorzystywana jest eksperymentalna ścieżka SG4, więc potraktuj pierwsze uruchomienie jako kalibrację."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Bezpieczeństwo"}},body:{t:0,b:{t:2,i:[{t:3}],s:"To gorący, ruchomy test, który celowo doprowadza do poślizgu ekstrudera. Załaduj filament, upewnij się, że dysza jest swobodna (nad stołem lub strefą odpadową) i pozostań w pobliżu. Uruchomienie jest odrzucane podczas drukowania, a grzałka jest zawsze wyłączana po zakończeniu."}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:"Wykorzystanie wyniku"}},body:{t:0,b:{t:2,i:[{t:3}],s:'Wpisz sugerowaną wartość do "maksymalnej prędkości objętościowej" w slicerze (dla danego filamentu). Wartość zachowawcza (80% zmierzonego maksimum) to bezpieczny limit na co dzień; wartość zrównoważona (90%) wyciska nieco więcej. Wyższe temperatury hotendu zwykle zwiększają osiągalny przepływ.'}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Słowniczek"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:"Przepływ objętościowy"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Ile plastiku hotend topi na sekundę (mm³/s) - rzeczywisty limit prędkości szybkiego druku."}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Sygnał sterownika TMC raportujący mechaniczne obciążenie silnika, tu używany do wykrywania poślizgu ekstrudera."}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:"Poślizg"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Gdy koło ekstrudera nie nadąża z chwytem filamentu i przeskakuje - sufit przepływu."}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:"Strefa topienia"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Grzana długość hotendu; dłuższa strefa topienia (np. Volcano) utrzymuje wyższy przepływ."}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:"Parametry testu"}},temperature:{t:0,b:{t:2,i:[{t:3}],s:"Temperatura (°C)"}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:"Ø filamentu (mm)"}},hotend:{t:0,b:{t:2,i:[{t:3}],s:"Hotend (opcjonalnie)"}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:"- brak -"}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:"Oczekiwane ~"},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:"Przepływ początkowy (mm³/s)"}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:"Przepływ końcowy (mm³/s)"}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:"Krok (mm³/s)"}},samples:{t:0,b:{t:2,i:[{t:3}],s:"Próbki / krok"}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:"Wytłaczanie / krok (mm)"}},driver:{t:0,b:{t:2,i:[{t:3}],s:"Sterownik ekstrudera"}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:"wykryty z drukarki"}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:"Automatycznie włącz StealthChop na czas testu"}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:"Tylko TMC2209/2240: tymczasowo zapisuje stealthchop_threshold do ekstrudera, aby StallGuard mógł odczytywać, po teście zakomentowuje to z powrotem. Przywraca printer.cfg; restart firmware w obie strony."}},method:{t:0,b:{t:2,i:[{t:3}],s:"Metoda wykrywania"}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:"Auto używa StallGuard, wracając do akcelerometru głowicy (wibracje), gdy StallGuard nie może odczytywać. Metoda akcelerometru jest eksperymentalna."}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:"Auto"}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},accel:{t:0,b:{t:2,i:[{t:3}],s:"Akcelerometr"}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:"Podejrzyj plan"}},title:{t:0,b:{t:2,i:[{t:3}],s:"Zaplanowane narastanie"}},stepCount:{t:0,b:{t:2,i:[{t:4,k:"count"},{t:3,v:" kroków"}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:"mm"},{t:3,v:" mm filamentu"}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:"Pole StallGuard: "},{t:4,k:"field"}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:"Brak znanego pola StallGuard dla tego sterownika"}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:"Przepływ (mm³/s)"}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:"Posuw (mm/min)"}},warning:{t:0,b:{t:2,i:[{t:3}],s:"Test na żywo nagrzewa hotend i wytłacza filament, celowo aż do poślizgu. To tylko podgląd - nic jeszcze nie jest uruchamiane."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Przed uruchomieniem - lista kontrolna bezpieczeństwa"}},items:[{t:0,b:{t:2,i:[{t:3}],s:"Filament jest załadowany i swobodnie się podaje."}},{t:0,b:{t:2,i:[{t:3}],s:"Dysza jest swobodna - nad stołem lub pojemnikiem na odpady, nie w powietrzu nad częściami."}},{t:0,b:{t:2,i:[{t:3}],s:"Akceptuję, że celowo zmieli/prześlizgnie się trochę filamentu."}},{t:0,b:{t:2,i:[{t:3}],s:"Pozostanę przy drukarce przez cały test."}}],ack:{t:0,b:{t:2,i:[{t:3}],s:"Wykonałem wszystkie powyższe punkty i drukarka jest gotowa"}},note:{t:0,b:{t:2,i:[{t:3}],s:"Uruchomienie jest odrzucane podczas drukowania; grzałka jest automatycznie wyłączana na końcu."}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:"Uruchom test na żywo"}},running:{t:0,b:{t:2,i:[{t:3}],s:"Trwa… (nagrzewanie + wytłaczanie)"}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:"Uruchomić test max-flow na żywo?"}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:"To nagrzewa hotend do "},{t:4,k:"temp"},{t:3,v:" °C i wytłacza do "},{t:4,k:"mm"},{t:3,v:" mm filamentu, zwiększając przepływ aż do poślizgu ekstrudera."}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Uruchom teraz"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Anuluj"}},busy:{t:0,b:{t:2,i:[{t:3}],s:"Odrzucono: drukarka jest zajęta (drukuje lub wstrzymana). Spróbuj ponownie, gdy będzie bezczynna."}},error:{t:0,b:{t:2,i:[{t:3}],s:"Test nie powiódł się."}},noSg:{t:0,b:{t:2,i:[{t:3}],s:"Nie odczytano żadnych próbek StallGuard - wynik poślizgu może być niewiarygodny. Pole SG sterownika na żywo prawdopodobnie wymaga dostosowania dla tego modelu."}},progress:{t:0,b:{t:2,i:[{t:3,v:"Krok "},{t:4,k:"step"},{t:3,v:"/"},{t:4,k:"total"},{t:3,v:" - "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:"Nagrzewanie / uruchamianie…"}},abort:{t:0,b:{t:2,i:[{t:3}],s:"Przerwij uruchomienie"}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:"Przerywanie…"}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:"Uruchomienie przerwane - grzałka została wyłączona."}},reattached:{t:0,b:{t:2,i:[{t:3}],s:"Ponownie podłączono: ten wynik zakończył się, gdy strona była nieaktywna."}},failed:{t:0,b:{t:2,i:[{t:3}],s:"Uruchomienie max-flow nie powiodło się."}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:"Przerwanie zawsze wyłącza grzałkę."}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:"Przed nagrzewaniem drukarka bazuje (jeśli trzeba) i centruje dyszę dla czystego widoku."}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:"Włączanie StealthChop…"}},homing:{t:0,b:{t:2,i:[{t:3}],s:"Bazowanie drukarki…"}},centering:{t:0,b:{t:2,i:[{t:3}],s:"Centrowanie dyszy…"}},heating:{t:0,b:{t:2,i:[{t:3}],s:"Nagrzewanie hotendu…"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Sprawdzanie sygnału StallGuard…"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"Zwiększanie przepływu…"}},reverting:{t:0,b:{t:2,i:[{t:3}],s:"Przywracanie konfiguracji…"}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:"Bazuj"}},center:{t:0,b:{t:2,i:[{t:3}],s:"Centruj"}},heat:{t:0,b:{t:2,i:[{t:3}],s:"Nagrzej"}},check:{t:0,b:{t:2,i:[{t:3}],s:"Sprawdź"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"Narastaj"}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:"Kamera na żywo"}},live:{t:0,b:{t:2,i:[{t:3}],s:"NA ŻYWO"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Kamera niedostępna."}},willShow:{t:0,b:{t:2,i:[{t:3}],s:"Widok kamery na żywo pokaże dyszę podczas testu."}},minimize:{t:0,b:{t:2,i:[{t:3}],s:"Minimalizuj"}},maximize:{t:0,b:{t:2,i:[{t:3}],s:"Maksymalizuj"}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:"Powiększ"}},shrink:{t:0,b:{t:2,i:[{t:3}],s:"Zmniejsz"}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:"Wynik"}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:"Maksymalny utrzymywany przepływ"}},slipAt:{t:0,b:{t:2,i:[{t:3,v:"Poślizg wykryty przy "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:"Brak poślizgu aż do najwyższego testowanego przepływu"}},reason:{t:0,b:{t:2,i:[{t:3}],s:"Szczegóły"}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:"Sugerowane wartości do slicera (maks. prędkość objętościowa)"}},conservative:{t:0,b:{t:2,i:[{t:3}],s:"Zachowawczo (80%)"}},balanced:{t:0,b:{t:2,i:[{t:3}],s:"Zrównoważona (90%)"}},units:{t:0,b:{t:2,i:[{t:3}],s:"mm³/s"}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:"Zmierzone wcześniej ("},{t:4,k:"at"},{t:3,v:") - uruchom ponownie po świeże wartości."}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:"Niewiarygodne - brak sygnału StallGuard"}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:"osiągnięte, niepotwierdzone"}},via:{t:0,b:{t:2,i:[{t:3,v:"Zmierzone metodą "},{t:4,k:"method"}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:"Zmierzone przez wibracje (akcelerometr) - eksperymentalne; traktuj wartość jako wskazówkę, a nie dokładny sufit."}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:"Ładowanie hotendów…"}}}}};export{t as default};
